/* 真题离线查看器：?code=13003&y=2024&m=10 → 渲染 papers/zikao/ 下的本地试卷图片 */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    const q = new URLSearchParams(location.search);
    const code = q.get("code"), y = parseInt(q.get("y", ""), 10), m = parseInt(q.get("m", ""), 10);
    const body = document.getElementById("pv-body");
    const idx = window.PAPERS_LOCAL || {};
    const list = idx[code] || [];
    const it = list.find(x => x.year === y && x.month === m);
    if (!it) {
      body.innerHTML = `<div class="notice empty"><strong>未找到本地镜像。</strong>该套真题尚未下载（当前仅 080901 计划内相关课程已本地化）。<br><a href="past-papers.html">← 返回历年真题合计</a></div>`;
      return;
    }
    const course = (SITE_DATA.zikao.courses.find(c => c.code === code) || {}).name || "";
    document.title = `${it.title} · 离线查看`;
    document.getElementById("pv-title").textContent = it.title;
    document.getElementById("pv-sub").textContent = `${code} ${course} · ${it.province}卷 · 共 ${it.pages} 页 · 本地镜像（个人备考使用，来源见下方链接）`;
    body.innerHTML =
      `<p class="pv-head"><a href="past-papers.html">← 返回真题合计</a> · 来源页面：<a href="${it.source_url}" target="_blank" rel="noopener">${it.source_url}</a></p>` +
      it.files.map(f => f.toLowerCase().endsWith(".pdf")
        ? `<iframe src="${it.dir}${f}" style="width:100%;max-width:900px;height:1100px;border:1px solid var(--rule);border-radius:8px;margin:0 auto 14px;display:block;" title="试卷 PDF"></iframe><p style="text-align:center;"><a class="badge ok" style="text-decoration:none;" href="${it.dir}${f}" download>下载试卷 PDF</a></p>`
        : `<img src="${it.dir}${f}" alt="第 ${f} 页" loading="lazy">`).join("") +
      `<p class="src">图片/PDF 本地镜像抓取自原始来源（2026-11-02），仅供个人备考使用，版权归原发布平台所有。</p>`;
  });
})();
